"""Sources, Dictionary, Changes."""
import re
from . import engine as E, snapshots as S, prep as P, curated as C
from .xl import Sheet, FX, FILL_WARN, FILL_BAD, FILL_OK

BASE, END = S.BASE, S.END
ACCESS = 'بسته شواهد v41 ارائه نشد و کدال در این جلسه پاسخ 503 یا قطع اتصال داد؛ متن سند باز نشد'


def sources_sheet(wb, m):
    heads = ['شناسه منبع', 'نماد', 'موضوع', 'عنوان سند', 'شماره ردیابی', 'دوره یا مقطع مربوط', 'تاریخ انتشار', 'صفحه فایل و شماره چاپی',
             'نشانی منبع', 'مسیر نسخه محلی (در بسته v41)', 'sha256 ثبت شده در رجیستری v41', 'وضعیت در رجیستری v41', 'دسترسی در این جلسه',
             'خلاصه ادعایی که سند پشتیبانی می کند', 'ادعاها یا برگه های استفاده کننده']
    sh = Sheet(wb, 'Sources v42', 'رجیستری منابع و مسیر شواهد',
               'هر شماره ردیابی که در بازتولید یا پنج پرونده به کار رفته یک ردیف دارد. اطلاعات از BR Sources v41 و از متن بازسازی v38 گرفته شده؛ متن اسناد در این جلسه باز نشد. جدول های حساس و اصلاحیه ها باید با صفحه اصلی کنترل شوند؛ استخراج متن به تنهایی برای رفع ابهام جدول کافی نیست.',
               heads, widths={1: 20, 2: 9, 3: 22, 4: 36, 5: 10, 6: 22, 7: 12, 8: 14, 9: 30, 10: 30, 11: 14, 12: 22, 13: 30, 14: 50, 15: 26},
               freeze='C4', raw_cols=(4,))
    reg = {str(r['tracing']): r for r in m['registry'] if r['tracing']}
    used = {}
    def add_use(tr, sym, topic, title, period, pub, url, claim, who):
        tr = str(tr)
        d = used.setdefault(tr, dict(sym=sym, topic=set(), title=title, period=period, pub=pub, url=url, claim=set(), who=set()))
        d['topic'].add(topic); d['who'].add(who)
        if claim:
            d['claim'].add(claim)
        if not d['title'] and title:
            d['title'] = title
        if not d['url'] and url:
            d['url'] = url
    fy_tr = {str(r['tracing']) for r in m['registry'] if r['type'].startswith('گزارش') and r['tracing']}
    for r in m['seat']:
        if r['tracing']:
            add_use(r['tracing'], r['sym'], 'بازسازی کرسی', r['src_title'], r['snapshot'], r['src_date'], r['url'],
                    f"فهرست {S._cutoff(r['snapshot'])}", 'Snapshot Members v42')
    for a in m['audit']:
        if a['tracing']:
            add_use(a['tracing'], a['sym'], 'رویداد کرسی', a['src_title'], a['year'], a['pub'], a['url'],
                    f"{a['change'] or a['var']}", 'Turnover Events v42')
    for ev in C.EVENTS:
        for tr in re.findall(r'\b1\d{6}\b', ev[10]):
            add_use(tr, ev[0], 'رویداد', '', '', '', '', f'{ev[2]}', 'Turnover Events v42')
    for cl in C.CLAIMS:
        for tr in re.findall(r'\b1\d{6}\b', cl[2] + ' ' + cl[5] + ' ' + cl[6]):
            add_use(tr, cl[0], 'پرونده', '', '', '', '', cl[1], 'Five Cases v42')
    for tr in list(used):
        if tr in fy_tr:
            del used[tr]
    # web pages and metadata leads logged in v39 (Sources v39) keep their original ids
    v39 = wb['Sources v39']
    v39rows = []
    for r in range(4, v39.max_row + 1):
        vals = [v39.cell(r, c).value for c in range(1, 10)]
        if vals[0]:
            v39rows.append(vals)
    for vals in v39rows:
        mt = re.search(r'\b1\d{6}\b', str(vals[3] or ''))
        if mt and mt.group(0) in used and not used[mt.group(0)]['url'] and vals[5] and str(vals[5]).startswith('http'):
            used[mt.group(0)]['url'] = vals[5]
        if mt and mt.group(0) not in used and mt.group(0) not in fy_tr and mt.group(0) not in reg:
            add_use(mt.group(0), vals[1] if vals[1] in m['scd'] else '', 'سرنخ v39', vals[2], str(vals[3]), '', vals[5] if str(vals[5]).startswith('http') else '', vals[7] or '', vals[0])
    for n, (tr, d) in enumerate(sorted(used.items(), key=lambda kv: (kv[1]['sym'], kv[0])), 1):
        rg = reg.get(tr)
        sym = d['sym']
        sh.add([f'V42S{n:03d}' if not rg else rg['sid'], sym, '؛ '.join(sorted(d['topic'])),
                (rg['title'] if rg else d['title']) or 'عنوان در رجیستری v41 نیست؛ از متن v38', int(tr),
                (d['period'] or '')[:60], P.d10(rg['pub']) if rg else (d['pub'] or ''), '', (rg['url'] if rg else d['url']) or '',
                (rg['path'] if rg else ''), (rg['sha'] if rg else ''),
                'در رجیستری v41' if rg else 'ردیف رجیستری ندارد؛ فقط از متن v38 یا Sources v39', ACCESS,
                '؛ '.join(sorted(d['claim']))[:200], '؛ '.join(sorted(d['who']))],
               fill=(None if rg else FILL_WARN), height=44)
    # FY1404 reports (registry) used for FYE and tenure
    for r in m['registry']:
        if r['type'].startswith('گزارش'):
            sc = m['scd'][r['sym']]
            sh.add([r['sid'], r['sym'], 'گزارش فعالیت هیئت مدیره FY1404؛ پایان دوره مالی و تصدی', r['title'] or 'ندارد', int(r['tracing']) if r['tracing'] else '',
                    f"مقطع {sc['fye']}", P.d10(r['pub']) if r['pub'] else '', '', r['url'] or '', r['path'] or '', r['sha'] or '',
                    'در رجیستری v41' if r['tracing'] else 'بدون ردیابی در رجیستری', ACCESS, 'تایید پایان دوره مالی FY1404 و تاریخ شروع عضویت', 'Scope v42؛ Person Flows v42'],
                   fill=(None if r['tracing'] else FILL_WARN), height=40)
    for vals in v39rows:
        if vals[0] in ('V39S01', 'V39S02', 'V39S03', 'V39S05', 'V39S09', 'V39S10'):
            sh.add([vals[0], vals[1] if vals[1] in m['scd'] else '', 'سرنخ v39 بدون شماره ردیابی', vals[2], '', str(vals[3] or '')[:60], '', '',
                    vals[5] if str(vals[5]).startswith('http') else '', '', '', 'فقط در Sources v39', ACCESS,
                    str(vals[7] or '')[:200], 'Five Cases v42'], fill=FILL_WARN, height=44)
    sh.autofilter()
    return sh, len(used)


def dictionary_sheet(wb, m):
    heads = ['کد یا قاعده', 'نام', 'وضعیت', 'تعریف', 'واحد', 'منبع داده', 'محدودیت و تفاوت با معیار دیگر', 'خانواده', 'توصیفی یا نامزد اعتبارسنجی']
    sh = Sheet(wb, 'Dictionary v42', 'فرهنگ داده v42: تعریف سنجه ها، قواعد تطبیق و دلیل تفاوت معیار فردی و کرسی',
               'کدهای قبلی بدون تغییر تعریف نگه داشته شده اند؛ تعریف واقعی آنها از فرمول ها و یادداشت های Turnover نهایی خوانده و با بازتولید هشت شرکت (80 مقدار از 80) تایید شد. مفاهیم جدید کد مکمل غیرمتداخل دارند. هیچ جهت نظری فرض نشده است.',
               heads, widths={1: 16, 2: 28, 3: 24, 4: 60, 5: 10, 6: 28, 7: 70, 8: 22, 9: 22}, freeze='B4')
    R = lambda *a: sh.add(list(a), height=70)
    R('REF05', 'گردش فردی مبتنی بر کرسی', 'کد قبلی؛ تعریف حفظ شد', 'صورت: تعداد کرسی های قابل مقایسه که شخص نامبرده در دو مقطع فرق دارد. مخرج: تعداد کرسی های قابل مقایسه (کرسی با نماینده معلوم در مبنا). برای عضو حقیقی مستقیم: افراد مبنا که در پایان نیستند تقسیم بر افراد مبنا.', 'نسبت', 'Turnover نهایی ستون G و H؛ بازتولید در Measures v42', 'در جابجایی همان افراد بین کرسی ها با نرخ خروج افراد یکتا فرق دارد: جم 2 از 5 در برابر 1 از 5 و خساپا 3 از 5 در برابر 2 از 5. این تفاوت خطا نیست.', 'خروج و ورود', 'توصیفی')
    R('REF08', 'تغییر نماینده با شخص حقوقی ثابت', 'کد قبلی؛ تعریف حفظ شد', 'صورت: کرسی های با همان شخص حقوقی که نماینده فرق دارد. مخرج: کرسی های با همان شخص حقوقی و نماینده معلوم در هر دو مقطع. کرسی متعلق به شخص حقوقی جایگزین شده وارد مخرج نمی شود.', 'نسبت', 'Turnover نهایی ستون J و K', 'اگر نرخ فقط برای کرسی های قابل مشاهده باشد نرخ کامل همه کرسی های ثابت نیست؛ سه شمارش جدا در Flow Summary v42: کل ثابت، با نماینده معلوم در هر دو مقطع، با نماینده نامشخص.', 'نمایندگی', 'توصیفی')
    R('ROB_LEGAL', 'تغییر شخص حقوقی', 'کد قبلی؛ تعریف حفظ شد', 'صورت: کرسی هایی که شخص حقوقی دارنده فرق دارد. مخرج: کرسی های موجود در هر دو مقطع.', 'نسبت', 'Turnover نهایی ستون M و N', 'تغییر نام با شناسه ثابت تغییر دارنده نیست؛ شناسه ملی اشخاص حقوقی در فایل نیست و مبنا نام است.', 'نمایندگی', 'توصیفی')
    R('ROB_NEW', 'سهم اعضای جدید', 'کد قبلی؛ تعریف حفظ شد', 'صورت: افراد پایان که در مبنا نبودند. مخرج: افراد پایان. عضو جدید یعنی جدید نسبت به مبنا، نه اولین عضویت در تاریخ شرکت.', 'نسبت', 'Turnover نهایی ستون P و Q', 'تعداد افراد جدید ممکن است از تعداد تغییرات کرسی کمتر باشد؛ شرط عمومی کمتر نبودن اعمال نشد.', 'خروج و ورود', 'توصیفی')
    R('ROB_STABILITY', 'ثبات کرسی با همان شخص', 'کد قبلی؛ تعریف حفظ شد', 'صورت: کرسی های قابل مقایسه با همان شخص. مخرج: کرسی های قابل مقایسه (برابر مخرج REF05).', 'نسبت', 'Turnover نهایی ستون S و T', 'ثبات کرسی با نرخ ماندگاری افراد یکتا یکی نیست: جم 3 از 5 در برابر 4 از 5.', 'خروج و ورود', 'توصیفی')
    R('CR1A', 'تغییر رئیس بین دو مقطع', 'کد قبلی؛ تعریف حفظ شد', 'صورت: 1 اگر هویت رئیس هیئت مدیره در دو مقطع فرق دارد، 0 اگر برابر؛ مبتنی بر تفاوت هویت در دو انتها.', 'دودویی', 'Turnover نهایی ستون V؛ CR1A v39', 'رئیس ثابت در دو انتها نبود تغییر میانی را اثبات نمی کند؛ تعداد رویدادهای مستند تغییر رئیس داخل دوره جدا در Turnover Events v42 است و تا کامل شدن زنجیره قطعی نیست. نام رئیس با نایب رئیس یا مدیرعامل یکی گرفته نشد.', 'رهبری', 'توصیفی')
    R('UPX1', 'نرخ خروج افراد یکتا', 'جدید؛ کد غیرمتداخل', 'صورت: تعداد افراد حقیقی یکتا که در فهرست کامل مبنا بودند و در فهرست کامل پایان نیستند. مخرج: تعداد اعضای فعال مبنا.', 'نسبت', 'Snapshot Members v42', 'فقط با دو فهرست کامل و بدون نماینده نامشخص؛ جای REF05 نشسته نیست. با UPR1 مکمل است و دو امتیاز مستقل نیست.', 'خروج و ورود', 'توصیفی؛ نامزد در مرحله بعد فقط با اجازه')
    R('UPN1', 'سهم افراد واردشده', 'جدید؛ کد غیرمتداخل', 'صورت: تعداد افراد یکتا که در فهرست پایان هستند و در مبنا نبودند. مخرج: تعداد اعضای فعال پایان.', 'نسبت', 'Snapshot Members v42', 'مخرج پایان است نه مبنا؛ جمع UPX1 و UPN1 نرخ گردش واحد نیست چون یک جانشینی هم خروج دارد و هم ورود.', 'خروج و ورود', 'توصیفی')
    R('UPR1', 'نرخ ماندگاری افراد یکتا', 'جدید؛ کد غیرمتداخل', 'صورت: تعداد افراد حاضر در هر دو مقطع. مخرج: تعداد اعضای فعال مبنا.', 'نسبت', 'Snapshot Members v42', 'UPX1 به علاوه UPR1 برابر یک است؛ در شاخص ترکیبی هر دو را به عنوان دو امتیاز مستقل نشمار.', 'خروج و ورود', 'توصیفی')
    R('UPF1', 'افراد یکتا در نمای مالی', 'جدید؛ نمای مالی', 'همان سه نسبت بین پایان دوره مالی 1403 و 1404 هر شرکت؛ فقط وقتی فهرست هر دو پایان معتبر و کامل باشد.', 'نسبت', 'Scope v42', 'در این مرحله برای هیچ شرکتی محاسبه نشد؛ مشاهدات این نما با پنجره مشترک در شمارش یکتا جمع نمی شود.', 'خروج و ورود', 'توصیفی')
    R('SCT1', 'شمارش کرسی های حقوقی ثابت', 'جدید؛ شمارش', 'کل کرسی های حقوقی با دارنده ثابت؛ تعداد دارای نماینده معلوم در هر دو مقطع؛ تعداد دارای نماینده نامشخص؛ تعداد خالی مستند.', 'تعداد', 'Flow Summary v42', 'نماینده نامشخص کمبود داده است نه غیرقابل اعمال و نه صفر تغییر.', 'نمایندگی', 'توصیفی')
    R('MATCH_PERSON', 'قاعده تطبیق فرد', 'قاعده', 'شناسه معتبر فرد در صورت وجود؛ در نبود آن نام یکسان سازی شده (یکسان سازی ی و ک، فاصله مجازی به فاصله، حذف اعراب) در همان شرکت. هیچ ادغام فازی انجام نمی شود.', '', 'names.py', 'کد ملی در فایل برای ردیف های بازسازی v38 نیست؛ مبنای هویت نام است و در Snapshot Members v42 ثبت شده است. تطبیق بین شرکت ها انجام نشد.', 'قاعده', '')
    R('MATCH_SEAT', 'قاعده تطبیق کرسی', 'قاعده', 'کرسی فقط با نام دارنده حقوقی یا جایگزینی مستند دارنده (ستون قبلی و جدید اطلاعیه) جفت می شود. شماره ردیف و ترتیب نام ها مبنا نیست. کرسی حقیقی مستقیم جفت نمی شود.', '', 'engine.py', 'شناسه پایدار کرسی در اسناد نیست؛ این محدودیت ثبت شد و تطبیق فرضی ساخته نشد.', 'قاعده', '')
    R('STATUS', 'واژگان وضعیت', 'قاعده', 'تاییدشده؛ تایید جزئی؛ متعارض؛ داده کافی پیدا نشد؛ منبع در دسترس نبود؛ هنوز بررسی نشده؛ از نظر تعریف قابل اعمال نیست.', '', 'curated.py', 'پیدا نشدن داده شرکت را خودکار از جمعیت واجد شرایط خارج نمی کند.', 'قاعده', '')
    R('COMPLETE', 'قاعده کامل بودن فهرست', 'قاعده', 'فهرست وقتی کامل است که همه کرسی ها نماینده نامبرده یا خالی بودن مستند داشته باشند و اعتبار سند و تاریخ آن برای همان مقطع بررسی شده باشد. تعداد کرسی مصوب با تعداد اعضای فعال یکی نیست.', '', 'snapshots.py', 'چهار نام در یک جدول به تنهایی کرسی پنجم خالی را اثبات نمی کند. عبارت فاقد نماینده به خالی بودن، خروج یا صفر تغییر تبدیل نشد.', 'قاعده', '')
    R('DATES', 'انواع تاریخ و مبنای زمانی', 'قاعده', 'تاریخ موثر، تاریخ جلسه، تاریخ مجمع و تاریخ انتشار جدا ثبت می شوند. مبنای مشترک 1403/12/29 و 1404/12/29 قراردادی است؛ 1403 کبیسه و آخرین روز آن 1403/12/30 است. نمای مالی پایان دوره هر شرکت را به کار می برد.', '', 'jalali.py', 'تاریخ نامشخص با روز ساختگی پر نمی شود. گزارش منتشرشده پس از مقطع فقط با متن صریح همان زمان وضعیت تاریخی را اثبات می کند.', 'قاعده', '')
    R('DIFF', 'چرا معیار فردی و کرسی فرق می کند', 'توضیح', 'REF05 کرسی محور است و جابجایی یک فرد بین دو کرسی را تغییر در هر دو کرسی می شمارد؛ نرخ خروج یکتا فرد محور است و آن جابجایی را خروج نمی شمارد. جم: نجفی و اکبری جابجا شدند و فقط نجفی رفت. خساپا: پرویزیان از کرسی رنا به کرسی سازمان مدیریت صنعتی رفت.', '', 'Flow Summary v42', 'در شرکت هایی که فرق دارند: جم و خساپا.', 'توضیح', '')
    return sh


